"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface MicAudioLinesIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface MicAudioLinesIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const MicAudioLinesIcon = forwardRef<
 MicAudioLinesIconHandle,
 MicAudioLinesIconProps
>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const capsuleVariants: Variants = {
   normal: { scale: 1 },
   animate: {
    scale: [1, 1.1, 0.96, 1],
    transition: {
     duration: 0.6 * duration,
     ease: "easeInOut",
     times: [0, 0.35, 0.7, 1],
    },
   },
  };

  const barVariants = (scale: number, delay: number): Variants => ({
   normal: { scaleY: 1 },
   animate: {
    scaleY: [1, scale, 1],
    transition: {
     duration: 0.6 * duration,
     ease: "easeInOut",
     delay: delay * duration,
    },
   },
  });

  const stubVariants = (shift: number, delay: number): Variants => ({
   normal: { y: 0 },
   animate: {
    y: [0, shift, 0],
    transition: {
     duration: 0.6 * duration,
     ease: "easeInOut",
     delay: delay * duration,
    },
   },
  });

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path
       d="M2 10v3"
       variants={barVariants(2.4, 0)}
       style={{ transformBox: "view-box", originX: "2px", originY: "11.5px" }}
      />
      <m.path
       d="M6 6v11"
       variants={barVariants(0.55, 0.05)}
       style={{ transformBox: "view-box", originX: "6px", originY: "11.5px" }}
      />
      <m.path d="M10 3v2.341" variants={stubVariants(1.2, 0.1)} />
      <m.path d="M14 5v.341" variants={stubVariants(-1.2, 0.15)} />
      <m.path
       d="M18 5v13"
       variants={barVariants(0.6, 0.2)}
       style={{ transformBox: "view-box", originX: "18px", originY: "11.5px" }}
      />
      <m.path
       d="M22 10v3"
       variants={barVariants(2.4, 0.25)}
       style={{ transformBox: "view-box", originX: "22px", originY: "11.5px" }}
      />
      <m.rect
       x="10"
       y="9"
       width="4"
       height="8"
       rx="2"
       variants={capsuleVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "13px" }}
      />
      <path d="M12 17v4" />
      <path d="M9 21h6" />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

MicAudioLinesIcon.displayName = "MicAudioLinesIcon";
export { MicAudioLinesIcon };
